test("marks a sent invoice overdue", () => {
  const invoice = { id: "R-7", customer: "Acme", cents: 990, status: "sent" } as const;
  assert.strictEqual(markOverdue(invoice).status, "overdue");
});

  return { ...invoice, status: "paid" };
}

export function markOverdue(invoice: Invoice): Invoice {
  if (invoice.status !== "sent") {
    throw new Error(`cannot mark overdue an invoice that is ${invoice.status}`);
  }
  return { ...invoice, status: "overdue" };
}
